def main():
    db = pd.read_excel("chess_database.xlsx", sheet_name="critical_positions")
    pbp = pd.read_csv("piece_by_piece_texts.csv").set_index("id")["piece_by_piece"]
    # professor's deliverable: exactly 4 columns
    with open("results.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f, quoting=csv.QUOTE_ALL)
        w.writerow(["id", "explanation_beginner", "explanation_intermediate", "explanation_advanced"])
        for _, r in db.iterrows():
            rid = int(r["id"]); b, i, a = EXPL[rid]
            w.writerow([rid, b, i, a])
    # extended context file (not the deliverable): metadata + evals + chessplainer piece-by-piece
    rows=[]
    for _, r in db.iterrows():
        rid=int(r["id"]); fen=r["fen_before"]; b,i,a=EXPL[rid]
        rows.append({"id":rid,"white":r["white"],"black":r["black"],
            "side_to_move":"White" if chess.Board(fen).turn else "Black",
            "critical_move":r["board move"],"fen":fen,
            "eval_before_cp":int(r["evaluation_before"]),"eval_after_cp":int(r["evaluaition_after"]),
            "piece_by_piece_chessplainer":pbp[rid],
            "explanation_beginner":b,"explanation_intermediate":i,"explanation_advanced":a})
    pd.DataFrame(rows).to_csv("chess_explanations_extended.csv", index=False, quoting=csv.QUOTE_ALL)
    print("wrote results.csv (4 columns) and chess_explanations_extended.csv")

if __name__ == "__main__":
    main()
